@startuml

class Sober {
}

class Car {
  + LicensePlate : string
}

class Owner {
  + Name : string
}

class Accident {
  + Date : date
  + Location : string
  + DamageAmount : double
}

class RideHail {
  + PickUpTime : datetime
  + DropOffTime : datetime
  + PickUpLocation : string
  + DropOffLocation : string
  + RideDuration : string
  + Distance : double
  + PassengerCount : int
  + Fee : double
  + RequestType : string
}

class RideShare {
  + PickUpTime : datetime
  + DropOffTime : datetime
  + PickUpLocation : string
  + DropOffLocation : string
  + RideDuration : string
  + Distance : double
  + PassengerCount : int
  + NegotiatedFee : double
}

class Customer {
  + Name : string
}

class RideShareCustomer {
  + Name : string
}

Car "0..*" -- "0..1" Owner : belongs to
Car "1" -- "0..*" Accident : involved in
Car "1" -- "0..*" RideHail : provides
Car "1" -- "0..*" RideShare : provides
RideHail "0..*" -- "1" Customer : lead customer
RideShare "0..*" -- "1..10" RideShareCustomer : passengers
Sober "1" -- "0..*" Car : operates
Sober "1" -- "0..*" RideHail : manages
Sober "1" -- "0..*" RideShare : manages

@enduml

